public class WordSplitter {

    public static String[] split(String s) {
        java.util.ArrayList<String> words = new java.util.ArrayList<>();
        for (String part : s.split("[^A-Za-z]+")) {
            if (!part.isEmpty()) {
                words.add(part);
            }
        }
        return words.toArray(new String[0]);
    }
}
